//! The session the runtime re-exports IS ikigai-module's: every checked-in vector decodes with
//! the wire-only mirrors and re-encodes to the same bytes. `tests/vectors/module-abi.txt` is a
//! verbatim copy of ikigai-module's `tests/vectors/module-abi.txt` (0.5.1, generated by its
//! `tests/abi_compat.rs` from values built with both shapes), so a drift between the two repos
//! is a failing test here, not a guest that silently stops decoding.

use ikigai_runtime::session::abi::{AbiModuleCall, AbiModuleReply};

const VECTORS: &str = include_str!("vectors/module-abi.txt");

fn hex(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2), "odd-length hex: {text}");
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digit"))
        .collect()
}

fn vectors() -> Vec<(&'static str, Vec<u8>)> {
    VECTORS
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .map(|line| {
            let (name, bytes) = line.split_once(' ').expect("`<Enum>.<Variant> <hex>`");
            (name, hex(bytes))
        })
        .collect()
}

#[test]
fn every_vector_decodes_and_re_encodes_to_the_same_bytes() {
    let mut calls = 0;
    let mut replies = 0;
    for (name, bytes) in vectors() {
        if name.starts_with("ModuleCall.") {
            let call = AbiModuleCall::decode(&bytes).unwrap_or_else(|e| panic!("{name}: {e}"));
            assert_eq!(call.encode().unwrap(), bytes, "{name}");
            calls += 1;
        } else if name.starts_with("ModuleReply.") {
            let reply = AbiModuleReply::decode(&bytes).unwrap_or_else(|e| panic!("{name}: {e}"));
            assert_eq!(reply.encode().unwrap(), bytes, "{name}");
            replies += 1;
        } else {
            panic!("unknown vector {name}");
        }
    }
    // Six calls and eight replies: every variant of both enums.
    assert_eq!((calls, replies), (6, 8));
}
